from pathlib import Path
import subprocess
R=Path(__file__).resolve().parents[1]
s=(R/"src/server/LobbyCompanions.luau").read_text(encoding="utf8")
bond=s[s.index(" function api.bond"):s.index(" function api.clear")]
rules=(R/'src/shared/LobbyRideRules.luau').read_text(encoding='utf8')
h='local RideRules=(function()\n'+rules+'\nend)()\nlocal at=10 local os={clock=function() return at end}\nlocal workspace={GetServerTimeNow=function() return at end}\nlocal sent=0 local P={CaptureRemote={FireAllClients=function() sent+=1 end}}\nlocal p={} local attributes={} local model={PrimaryPart={Position=0},SetAttribute=function(_,k,v) attributes[k]=v end,GetAttribute=function(_,k) return attributes[k] end}\nlocal pets={[p]={id=7,model=model}}\nlocal distance=5 local rootExists=true local action=true local lobby=true local available=true\nlocal rr={Position=setmetatable({},{__sub=function() return {Magnitude=distance} end})}\nlocal function root() return rootExists and rr or nil end\nlocal context={canAct=function() return action end,inLobby=function() return lobby end,bag=function() return {} end}\nlocal Rules={find=function() return {} end,available=function() return available end}\nlocal api={}\n'+bond+'\nassert(not api.bond({},7)) assert(not api.bond(p,8))\ndistance=11 assert(not api.bond(p,7)) distance=5\nrootExists=false assert(not api.bond(p,7)) rootExists=true\nlobby=false assert(not api.bond(p,7)) lobby=true\naction=false assert(not api.bond(p,7)) action=true\navailable=false assert(not api.bond(p,7)) available=true\nfor _,star in ipairs({3,6,9}) do attributes.Stars=star assert(not api.bond(p,7)) end attributes.Stars=1\nassert(api.bond(p,7) and sent==1 and attributes.PetBondUntil==13)\nassert(not api.bond(p,7)) at=13.5 assert(api.bond(p,7) and sent==2)\nprint("BOND_AUTH_PASS: ownership, distance, lobby, locks, cooldown")\n'
(R/".tools/test_pet_bond.luau").write_text(h,encoding="utf8")
subprocess.run([str(R/".tools/luau/luau.exe"),".tools/test_pet_bond.luau"],cwd=R,check=True)
